# Generates src/icons_lucide.lua (embedded default set) from icons/lucide.lua (Footagesus/Icons, MIT).
import re, sys, os
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
text = open(os.path.join(root, "icons", "lucide.lua"), encoding="utf-8").read()
pairs = re.findall(r'\["([^"]+)"\]\s*=\s*"rbxassetid://(\d+)"', text)
out = ["-- Lucide icons (name -> asset id), generated by tools/gen_lucide.py from Footagesus/Icons (MIT, see icons/LICENSE).",
       "-- Do not edit by hand.", "return {"]
line = []
for name, asset in pairs:
    line.append('["%s"]=%s,' % (name, asset))
    if len(line) == 6:
        out.append("\t" + "".join(line)); line = []
if line: out.append("\t" + "".join(line))
out.append("}")
open(os.path.join(root, "src", "icons_lucide.lua"), "w", encoding="utf-8").write("\n".join(out) + "\n")
print("lucide icons:", len(pairs))
